    try { const v = getVariables({ type: 'message', message_id: i }); return v && v.stat_data && v.stat_data.World ? v.stat_data : null; } catch (e) { return null; }
  }
  function prevState() {
    for (let i = MID - 1; i >= 0; i--) { const s = stateAt(i); if (s) return s; }
    return null;
  }
  let deltaOpen = false;   // the fold stays open across redraws of this bracelet (not stored)
  let feedOpen = false;    // 2.1.0: the same for Campus now
  // stale only when a later VISIBLE message carries its own bracelet (older chats have hidden Builder entries with a placeholder)
  function isLatest() {
    try {
      const last = getLastMessageId();
      if (MID < 0 || MID >= last) return true;
      return !getChatMessages(MID + 1 + '-' + last).some(m => !m.is_hidden && String(m.message || '').includes(PH));
    } catch (e) { return true; }
  }
  function bar(label, cur, max, color, sub, cls) {
    const pct = max > 0 ? Math.max(0, Math.min(100, cur / max * 100)) : 0;
    return '<div class="vit"><div class="row"><span>' + label + '</span><b>' + fmt(cur) + ' <small>/ ' + fmt(max) + '</small></b></div>'
      + '<div class="bar"><i style="width:' + pct + '%;background-color:' + color + '"></i></div>'
      + '<div class="sub ' + (cls || '') + '">' + esc(sub) + '</div></div>';
  }
  function chip(text, icon, cls, title, open) {   // open: panel target -> the chip becomes a button (5.1)
    const tag = open ? 'button' : 'span';
    return '<' + tag + ' class="chip ' + (cls || '') + '"' + (open ? ' data-open="' + esc(open) + '"' : '') + (title ? ' title="' + esc(title) + '"' : '') + '><i class="fa-solid ' + icon + '"></i>' + esc(text) + '</' + tag + '>';
  }
  const sevCls = c => /Dead|Unconscious|Critical|Badly/.test(c) ? 'bad' : /Hurt/.test(c) ? 'mid' : '';
  const fatCls = f => /Collapsed|Exhausted/.test(f) ? 'bad' : /Tired/.test(f) ? 'mid' : '';

  // 1.3.5 (owner playtest: a card imported without its lorebook left "Syncing the bracelet…" forever). The starting state comes
  // from the card's lorebook ([initvar]); without it MVU has nothing to show. After a few seconds with no state, say why and
  // offer SillyTavern's own "Import Card Lore" (character panel → More…; it asks before overwriting and links the lorebook).
  function lorebookStatus() {   // 'missing' | 'ok' | '' (cannot tell)
    try {
      const wb = getCharWorldbookNames('current'), names = getWorldbookNames();
      return wb && wb.primary && names.includes(wb.primary) ? 'ok' : 'missing';
    } catch (e) { return ''; }
  }
  function diagnose() {
    const st = lorebookStatus();
    const why = st === 'ok'
      ? 'No game state in this chat. The card\'s lorebook is attached, so check that <b>MagVarUpdate</b> and <b>Tavern Helper</b> are enabled, then start a new chat.'
      : 'No game state: the <b>card\'s lorebook is not attached</b> to this character' + (st ? '' : ' (or MagVarUpdate is not running)') + '. Import it (SillyTavern asks before overwriting), then start a <b>new chat</b>: the opening message takes its starting state from the lorebook.';
    band.className = 'band';
    band.innerHTML = '<div class="cta"><span>' + why + '</span>' + (st === 'ok' ? '' : '<button class="btn primary" data-importlore="1">Import the card\'s lorebook</button>') + '</div>';
  }
  function importLore() {   // SillyTavern: character panel → More… → Import Card Lore
    try {
      const pd = window.parent.document, sel = pd.getElementById('char-management-dropdown'), opt = pd.getElementById('import_character_info');
      if (!sel || !opt) throw new Error('menu not found');
      sel.selectedIndex = Array.from(sel.options).indexOf(opt);
      sel.dispatchEvent(new Event('change', { bubbles: true }));
    } catch (e) {
      band.querySelector('.cta span').innerHTML += '<br>Open the character panel → <b>More…</b> → <b>Import Card Lore</b>.';
    }
  }

  // 1.25.0 (owner, planning/DRAFT_proficiency_practice.md Batch 1): red "new" dots. Shared by the bracelet and the panels
  // (tools/gen_ui.py pastes this file into both). What was seen is not game state: it lives in Tavern Helper's chat variables
  // (chat_metadata.variables, saved with the chat; MVU only writes its own keys there), never in the message variables or the
  // browser (DECISIONS §6, §11). The panels write it; the bracelet only reads it.
  // An item is [key, panel]. Two levels: a panel button's dot goes once the panel is opened ("noticed"); an item's dot goes once
  // the item itself is shown ("seen").
  const NEWS_VAR = 'eld_seen';
  function newsItems(S, featOn) {
    const ui = (S && S.$ui) || {}, unl = ui.unlocks || [], out = [];
    const tab = (panel, id, ok) => { if (ok) out.push(['tab:' + panel + ':' + id, panel]); };
    const f = id => featOn(id), u = k => unl.includes(k);
    tab('notebook', 'bag', u('inventory') && f('inventory'));   // 1.32.0: the Bag is in Inventory
    tab('notebook', 'notices', u('notices') && (f('notices') || f('weather')));
    tab('notebook', 'letters', u('letters') && f('letters'));
    tab('notebook', 'mystery', u('mystery') && f('mystery'));
    tab('activities', 'competition', u('competition') && f('competition'));
    tab('activities', 'projects', u('projects') && f('projects'));
    tab('activities', 'trip', u('trip') && f('trip'));
    const practiceNames = ["Potion Halls","Main Library","Study Rooms","Archive","Seminar Rooms","Observation Tower","Meditation Rooms","Spirit Path","Willow Island","Club Rooms","Combat Grounds","The Sparring Pavilion","Gymnasium","Sports Field","Archery Range","Swimming Pool","Gardens","Menagerie","Bell Tower","Boathouse and Lake","Grassy Field and Hills","Forest","Forest Clearing","Fishing House","The Mall","Common Rooms","Workshop","Canteen","Courtyards","Fire Dormitory","Light Dormitory","Sky Dormitory","Viridian Dormitory"];   // 1.43.0: every place with a Practice action (data/practice.json)
    const practiceHere = practiceNames.some(n => (ui.discovered || []).includes(n));
    tab('activities', 'practice', practiceHere && f('proficiency'));
    if (f('proficiency')) {
      for (const [k, v] of Object.entries((((S || {}).Player || {})._Proficiency || {}))) if (+v > 0) out.push([`stat:${k}:${v}`, 'profile']);
      (ui.discovered || []).forEach(n => { if (practiceNames.includes(n)) out.push(['act:' + n.toLowerCase().replace(/^the /,'').replace(/[^a-z0-9]+/g,'_').replace(/_$/,'') , 'activities']); });
    }
    tab('profile', 'hidden', !!((S && S.Hidden) || {})._True_magic || u('hidden'));
    tab('profile', 'perks', Object.keys((S && S._Perks) || {}).length > 0 || (ui.perks_used || []).length > 0);
    (ui.lore || []).forEach(x => out.push(['lore:' + x, 'map']));
    Object.keys((S && S.Bonds) || {}).forEach(id => out.push(['npc:' + id, 'people']));
    return out;
  }
  function newsStore() {
    try { const v = (getVariables({ type: 'chat' }) || {})[NEWS_VAR]; return v && Array.isArray(v.seen) ? v : null; } catch (e) { return null; }
  }
  // keys not yet seen; with `panels`, the panels holding one that is not noticed either (the bracelet buttons)
  function newsUnseen(S, featOn, st) {
    if (!S || !st) return [];
    const seen = new Set(st.seen);
    return newsItems(S, featOn).filter(([k]) => !seen.has(k));
  }
  function newsPanels(S, featOn, st) {
    const noticed = new Set((st && st.noticed) || []);
    return new Set(newsUnseen(S, featOn, st).filter(([k]) => !noticed.has(k)).map(([, p]) => p));
  }
  const newsDot = label => '<i class="nd" role="img" aria-label="' + (label ? label + ', ' : '') + 'new" title="New"></i>';

  let who = id => id;
  function render() {
    if (!isLatest()) { band.className = 'band stale'; band.innerHTML = ''; return; }
    const S = readState();
    // v1.0.3 (A#5, D14): an NPC is named once Rank >= 1 or the story named them; before that, their descriptor
    who = id => (CAST[id] ? ((((S || {}).Bonds || {})[id] || {}).Rank >= 1 || (((S || {}).$ui || {}).names || []).includes(id) ? CAST[id][2] : CAST[id][1]) : id);
    if (!S) { band.className = 'band'; band.innerHTML = '<div class="waiting">Syncing the bracelet…</div>'; return; }
    const W = S.World || {}, P = (S.Player || {}).Profile || {}, V = (S.Player || {}).Vitals || {};
    const ui = S.$ui || {}, unl = ui.unlocks || [], M = S.Magic || {}, T = M._Techniques || {}, H = S.Hidden || {};
    band.style.setProperty('--dorm', DORM[P.Dorm] || DORM.Unsorted);
    const upkeep = Object.values(M.Active || {}).reduce((a, e) => a + num((T[e.Technique] || {}).Upkeep_per_min, 0), 0);

    // 1.9.4 (playtest Batch 4): season beside Month/Week (shared.js SEASONS, as the engine), and the temperature when Weather is on
    const wx = ui.wx, wxm = ui.wxfx || 'full', wxOn = wxm !== 'off' && wx && wx.now && !wx.away && W._Weather;
    const season = SEASON_OF(W.Month);
    let h = '<div class="top"><div class="glass">'
      + '<div class="clock"><span class="dy">' + esc(W.Day) + '</span><span class="t">' + esc(W.Time) + '</span><span class="d">Month ' + esc(W.Month) + ', Week ' + esc(W.Week)
      + ' · ' + season + (wxOn ? ' · <b class="tc" title="' + esc(W._Weather) + '">' + esc(wx.now.temp) + ' °C</b>' : '') + '</span></div>'
      + '<div class="period">' + esc(W._Period || 'Free time') + '</div>'
      + '<div class="loc"><i class="fa-solid fa-location-dot"></i> ' + esc(W.Location) + '</div>'
      + '</div><div class="side"><div class="pts"><b>' + fmt((S.Player.Wallet || {}).Points) + '</b><small>points</small></div>'
      + '<div class="dorm"><i class="gem" aria-hidden="true"></i>' + esc(P.Dorm === 'Unsorted' || !P.Dorm ? 'Unsorted' : P.Dorm + (P.Dorm_rank ? ' #' + P.Dorm_rank : '')) + '</div></div></div>';

    h += '<div class="vitals">'
      + bar('Health', num(V.HP, 0), num(V.HP_max, 100), 'var(--hp)', V._Condition || '', sevCls(V._Condition || ''))
      + bar('Stamina', num(V.Stamina, 0), num(V.Stamina_max, 100), 'var(--st)', V._Fatigue || '', fatCls(V._Fatigue || ''))
      + bar('Mana', num(V.Mana, 0), num(V.Mana_max, 100), 'var(--mp)', upkeep > 0 ? 'Upkeep −' + fmt(upkeep) + '/min' : (Object.keys(T).length ? Object.keys(T).length + ' techniques' : 'No techniques yet'), upkeep > 0 ? 'mid' : '')
      + '</div>';

    const c = [];
    // 1.1.0: features that are off hide their chips (Student file > Settings > Features)
    const OFF = ui.off || [], on = id => !OFF.includes(id);
    if (wxOn) {
      const n = wx.now, ic = n.rare === 'lightning storm' ? 'fa-bolt' : n.sky === 'Storm' ? 'fa-cloud-bolt' : n.snow ? 'fa-snowflake' : n.sky === 'Rain' ? (n.rain === 'heavy' ? 'fa-cloud-showers-heavy' : 'fa-cloud-rain')
        : n.sky === 'Fog' ? 'fa-smog' : n.sky === 'Overcast' ? 'fa-cloud' : n.sky === 'Cloudy' ? 'fa-cloud-sun' : n.wind ? 'fa-wind' : wx.block === 2 ? 'fa-moon' : 'fa-sun';
      const sky = n.rare || (n.snow ? 'snow' : n.sky === 'Rain' ? (n.rain ? n.rain + ' rain' : 'rain') : String(n.sky || '').toLowerCase());
      c.push(chip(sky + (n.wind && n.rare !== 'blizzard' ? ', ' + n.wind : ''), ic, n.rare ? 'warn' : '', W._Weather));
    }
    if (wxm === 'full' && unl.includes('conditions')) {
      const CI = { Soaked: 'fa-droplet', Chilled: 'fa-temperature-low', Overheated: 'fa-temperature-high', 'Head cold': 'fa-head-side-cough' };
      Object.entries((S.Player || {}).Conditions || {}).forEach(([k, v]) => c.push(chip(k, CI[k] || 'fa-circle-exclamation', 'warn', (v && v.Effect) || k, 'profile')));
    }
    if (W._Event_today) c.push(chip(W._Event_today.split(/ \| |;/)[0].split(' — ')[0].split(' (')[0], 'fa-star', 'glow', W._Event_today, (ui.ev || []).length ? 'activities:event' : ''));   // 1.81.0: opens the Event tab
    if ((ui.ev || []).some(e => e && e.stall) || (ui.cw && ui.cw.stall)) c.push(chip('Stalls here', 'fa-store', '', 'Open the stalls here', 'activities:shop'));   // 1.81.0; 1.90.0 club stalls
    if (ui.cw && ui.cw.svc) c.push(chip('Services here', 'fa-scissors', '', "Open the club's services", 'activities:shop'));   // 1.91.0
    // 1.3.4 (owner): what comes next today (engine $ui.next): an event's timed item, a class, curfew; 1.44.0 an appointment
    const nx = ui.next;
    if (nx && nx.at) c.push(chip('Next ' + nx.at + ' · ' + nx.what, nx.kind === 'curfew' ? 'fa-moon' : nx.kind === 'class' ? 'fa-book-open' : nx.kind === 'plan' ? 'fa-thumbtack' : 'fa-clock', nx.kind === 'event' ? 'glow' : '', 'Next today: ' + nx.at + ', ' + nx.what, 'notebook:planner'));
    if (ui.training) c.push(chip(ui.training, 'fa-bed', 'warn'));
    if (wxm === 'full' && ui.sleep && ui.sleep.loss) c.push(chip('Sleep debt: −' + Math.round(ui.sleep.loss * 100) + '% stamina', 'fa-bed', 'warn', ui.sleep.nights ? 'The Vigil: ' + ui.sleep.nights + ' full nights owed' : 'One sleep of at least 6 hours clears the debt'));
    if (W._Curfew) c.push(chip(/LOCKDOWN/.test(W._Curfew) ? 'Lockdown' : /Break/.test(W._Curfew) ? 'Break' : /^Away/.test(W._Curfew) ? 'Away' : 'Curfew', /^Away/.test(W._Curfew) ? 'fa-route' : 'fa-moon', /LOCKDOWN|CURFEW/.test(W._Curfew) ? 'danger' : 'warn', W._Curfew));
    const inj = Object.keys((S.Player || {}).Injuries || {});
    if (unl.includes('injuries') && inj.length) c.push(chip(inj.length === 1 ? inj[0] : inj.length + ' injuries', 'fa-bandage', 'danger', inj.join(', ')));
    const act = Object.keys(M.Active || {});
    if (act.length) c.push(chip(act.join(', '), 'fa-wand-sparkles', 'glow', 'Active effects'));
    const summoned = Object.entries(M.Pacts || {}).filter(([, p]) => p.Summoned).map(([k]) => k);
    if (unl.includes('pacts') && summoned.length) c.push(chip(summoned.join(', ') + ' summoned', 'fa-feather', 'glow'));
    if (unl.includes('hidden') && (H._True_magic || ui.dove)) c.push(chip('Doves: ' + (H._Stage || 'Unnoticed'), 'fa-eye', num(H.Dove_attention, 0) >= 40 ? 'danger' : num(H.Dove_attention, 0) >= 20 ? 'warn' : '', 'Dove attention ' + num(H.Dove_attention, 0) + '/100'));
    if ((S.Battle || {}).Active && on('battle')) c.push(chip('In battle: ' + Object.keys(S.Battle.Combatants || {}).map(k => CAST[k] && !(((S.Bonds || {})[k] || {}).Rank >= 1 || (ui.names || []).includes(k)) ? CAST[k][1] : k).join(', '), 'fa-khanda', 'danger', 'Open the battle panel', 'battle'));
    // 1.44.0: overdue and due today from the engine's Agenda feed (commitments and projects)
    const com = on('planner') ? Object.entries(S.Commitments || {}) : [], ag = (Array.isArray(ui.agenda) ? ui.agenda : []).filter(x => x.k === 'commitment' || x.k === 'project');
    const late = ag.filter(x => x.s === 'overdue').map(x => x.t), soon = ag.filter(x => x.s !== 'overdue' && x.d === 0).map(x => x.t);
    if (late.length) c.push(chip('Overdue: ' + late.join(', '), 'fa-triangle-exclamation', 'danger', 'Open the planner', 'notebook:planner'));
    else if (soon.length) c.push(chip('Due today: ' + soon.join(', '), 'fa-thumbtack', 'warn', 'Open the planner', 'notebook:planner'));
    else if (unl.includes('planner') && com.length) c.push(chip(com.length + (com.length === 1 ? ' commitment' : ' commitments'), 'fa-thumbtack', '', com.map(([k]) => k).join(', '), 'notebook:planner'));
    const mail = Object.values(S.Letters || {}).filter(l => l && l.Status === 'waiting').length;
    if (unl.includes('letters') && mail && on('letters')) c.push(chip(mail === 1 ? 'Letter waiting' : mail + ' letters waiting', 'fa-envelope', 'glow', 'At the Mail Tower', 'notebook:letters'));
    const hap = ui.hap;   // 5.3 (F20): today's campus happening
    if (hap && hap.text && ui.happenings !== 'off') c.push(chip((hap.now ? 'Now: ' : hap.from + ':00 ') + (hap.where || 'Around campus'), 'fa-bullhorn', hap.now ? 'glow' : '', hap.text, 'notebook:planner'));
    // 1.2.0: at a shop (Commissary, the Mall and its shops) a chip opens the Shop tab, which exists only there
    if (/^(the\s+)?(commissary|mall|nightwell|merryhew'?s|snug|quillfeather'?s|pennywhistle curios|barrow & vine|greenwick'?s|tinker'?s bench|salaffian oven|tailor'?s row)\b/i.test(String(W.Location || '').trim())) c.push(chip('Shop here', 'fa-basket-shopping', '', 'Open the shop list', 'activities:shop'));
    if (c.length) h += '<div class="chips">' + c.join('') + '</div>';

    const low = h.length;   // 1.22.0: who is here and the latest news share one row (.low)
    const here = Object.entries((S.Scene || {}).Present || {});
    // 1.70.0: while the Eldrasil UI script runs, the scene cards under the reply show who is here (portrait, thoughts, bond)
    let cards = false; try { cards = !!window.parent.__eldrasilScene; } catch (e) { /* no parent */ }
    if (here.length && !cards) {
      h += '<div class="cast" aria-label="Here with you">' + here.map(([id, v]) => {
        const c = CAST[id], b = (S.Bonds || {})[id];
        const known = c && ((b && b.Rank >= 1) || (ui.names || []).includes(id));
        const label = c ? (known ? c[2] : c[1]) : id;
        const mood = wxm !== 'off' && b && b.Rank >= 4 && (ui.moods || {})[id];
        const moodIcon = mood ? '<span class="md' + (mood.day ? ' sd' : '') + '" title="' + esc(mood.mood + ' mood' + (mood.day ? ': ' + mood.tone + ' (' + mood.day + ')' : '')) + '"><i class="fa-solid ' + ({ Good: 'fa-sun', Bad: 'fa-cloud' }[mood.mood] || 'fa-circle') + '"></i></span>' : '';   // 1.22.0: a badge on the portrait
        const tip = label + (v && v.Note ? ': ' + v.Note : '');
        const face = c && c[0] ? '<img class="face" style="--ring:' + c[3] + '" src="' + esc(BASE + c[0]) + '" alt="" data-fb="' + (known ? esc(c[2].slice(0, 2)) : '?') + '">'
          : '<span class="face" style="--ring:' + (c ? c[3] : 'var(--rule2)') + '">' + esc(c && !known ? '?' : id.split(/\s+/).map(w => w[0]).join('').slice(0, 2)) + '</span>';   // 1.7.0: no portrait yet
        // 1.6.1 (N5): an invented character's button pins them in the Extras record (Keep) or lets them go
        const xr = !c ? ((S.Extras || {})[id] || null) : null, pin = xr && xr.Keep;
        const xtip = !c ? (pin ? ' (kept: tap to let them go)' : ' (tap to keep them in the record of invented characters)') : '';
        return '<button ' + (c ? 'data-open="npc:' + esc(id) + '"' : 'data-keep="' + esc(id) + '"') + ' title="' + esc(tip + xtip) + '">' + face + '<span class="nm">' + (pin ? '<i class="fa-solid fa-thumbtack"></i> ' : '') + esc(known || !c ? (c ? c[2] : id) : '?') + '</span>' + moodIcon + '</button>';
      }).join('') + '</div>';
    }

    const news = (ui.toasts || []).slice(-4).map(t => String(t).replace(/\{npc:([^}]+)\}/g, (_m, id) => who(id)));
    if (news.length) h += '<div class="news">' + news.map(t => '<div>' + esc(t) + '</div>').join('') + '</div>';
    if (h.length > low) h = h.slice(0, low) + '<div class="low">' + h.slice(low) + '</div>';

    // 2.1.0 (owner roadmap R1): Campus now, folded like "This reply": the few the engine drew this block ($ui.feed, shared.js
    // campusFew); the People panel's Campus now tab lists everyone. Only for the player: the narrator never reads it.
    const feed = Array.isArray(ui.feed) ? ui.feed.filter(x => Array.isArray(x) && x[0]) : [];
    if (feed.length) {
      h += '<details class="delta cnow"' + (feedOpen ? ' open' : '') + '><summary>Campus now <small>' + feed.length + ' of the people you know</small></summary><div class="cn">'
        + feed.map(x => '<div><button class="lnk" data-open="npc:' + esc(x[0]) + '">' + esc(who(x[0])) + '</button> : ' + esc(x[1] || '') + (x[2] ? ' - ' + esc(x[2]) : '') + '</div>').join('')
        + '<button class="lnk more" data-open="people:now">Everyone on the People panel</button></div></details>';
    }

    // 1.79.0 (Megumin audit MS1): everything the engine changed in this reply, folded; worked out here from this message's state and
    // the one before it, so it costs no prompt and adds nothing to the saved chat
    const S0 = prevState(), S1 = stateAt(MID);
    const dl = S0 && S1 ? replyDelta(S0, S1) : [];
    if (dl.length) {
      const groups = DELTA_GROUPS.filter(g => dl.some(r => r[0] === g)), name = t => String(t).replace(/\{npc:([^}]+)\}/g, (_m, id) => who(id));
      h += '<details class="delta"' + (deltaOpen ? ' open' : '') + '><summary>This reply <small>' + dl.length + (dl.length === 1 ? ' change' : ' changes') + '</small></summary>'
        + groups.map(g => '<div class="dg"><span class="dgh">' + g + '</span>' + dl.filter(r => r[0] === g).map(r => '<div>' + esc(name(r[1])) + '</div>').join('') + '</div>').join('')
        + '</details>';
    }

    if (!ui.built) h += '<div class="cta"><span>Your student file is empty. Set up your student before your first action.</span><button class="btn primary" data-open="builder">Create your student</button></div>';

    // 1.25.0: a red dot on a button whose panel holds something new the player has not looked at (news.shared.js)
    const featOn = id => (typeof (ui.on || {})[id] === 'boolean' ? ui.on[id] : !OFF.includes(id)), nst = newsStore();
    const NP = newsPanels(S, featOn, nst), nd = p => (NP.has(p) ? newsDot() : '');
    h += '<div class="actions"><button class="btn" data-open="profile"><i class="fa-solid fa-id-card"></i> Student file' + nd('profile') + '</button>'
      + '<button class="btn" data-open="people"><i class="fa-solid fa-users"></i> People' + nd('people') + '</button>'
      + '<button class="btn" data-open="map"><i class="fa-solid fa-map"></i> Map' + nd('map') + '</button>'
      + '<button class="btn" data-open="notebook"><i class="fa-solid fa-bag-shopping"></i> Inventory' + nd('notebook') + '</button>'
      + '<button class="btn" data-open="activities"><i class="fa-solid fa-compass"></i> Activities' + nd('activities') + '</button>'
      + (!ui.built ? '<button class="btn opt" data-open="builder"><i class="fa-solid fa-pen-nib"></i> Builder</button>' : '')
      + '<button class="btn ghost" data-toggle="1" aria-label="Collapse or expand" aria-expanded="' + (!collapsed) + '" title="' + (collapsed ? 'Expand' : 'Collapse') + '"><i class="fa-solid ' + (collapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button></div>';

    band.className = 'band' + (collapsed ? ' collapsed' : '');
    band.innerHTML = h;
    band.querySelectorAll('img[data-fb]').forEach(img => img.addEventListener('error', () => {
      const sp = document.createElement('span'); sp.className = 'face'; sp.style.cssText = img.style.cssText; sp.textContent = img.dataset.fb; img.replaceWith(sp);
    }, { once: true }));
    popToasts(news);
  }

  function popToasts(news) {
    if (!news.length || typeof toastr === 'undefined') return;
    let chat = ''; try { chat = SillyTavern.getCurrentChatId(); } catch (e) {}
    const key = 'eld.toast.' + chat + '.' + MID + '.' + news.join('|').length + news.join('|').slice(0, 60);
    try { if (sessionStorage.getItem(key)) return; sessionStorage.setItem(key, '1'); } catch (e) { return; }
    news.forEach(t => toastr.info(t, 'Bracelet', { timeOut: 4500 }));
  }

  band.addEventListener('toggle', ev => { const l = ev.target.classList; if (!l || !l.contains('delta')) return; if (l.contains('cnow')) feedOpen = ev.target.open; else deltaOpen = ev.target.open; }, true);
  band.addEventListener('click', ev => {
    const b = ev.target.closest('button'); if (!b) return;
    if (b.dataset.importlore) { importLore(); return; }
    if (b.dataset.toggle) { collapsed = !collapsed; try { localStorage.setItem('eld.bar.collapsed', collapsed ? '1' : '0'); } catch (e) {} render(); return; }
    if (b.dataset.keep) {
      if (!window.parent.__eldrasilUI) { if (typeof toastr !== 'undefined') toastr.warning('Turn on the "Eldrasil UI" script in Tavern Helper → Scripts.', 'Eldrasil'); return; }
      eventEmit('eldrasil:keep', b.dataset.keep); return;
    }
    if (b.dataset.open) {
      if (!window.parent.__eldrasilUI) { if (typeof toastr !== 'undefined') toastr.warning('Turn on the "Eldrasil UI" script in Tavern Helper → Scripts.', 'Eldrasil'); return; }
      eventEmit('eldrasil:open', b.dataset.open);
    }
  });

  const rerender = _.debounce(render, 250);
  try {
    ['MESSAGE_RECEIVED', 'MESSAGE_SENT', 'MESSAGE_DELETED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED', 'MESSAGE_EDITED', 'CHAT_CHANGED'].forEach(k => {
      if (tavern_events[k]) eventOn(tavern_events[k], rerender);
    });
    eventOn('eldrasil:state', rerender);
    eventOn('eldrasil:news', rerender);   // 1.25.0: a panel marked something as seen
    waitGlobalInitialized('Mvu').then(() => {
      eventOn(Mvu.events.VARIABLE_INITIALIZED, rerender);
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => setTimeout(rerender, 400));
    });
  } catch (e) { console.warn('[Eldrasil bar]', e); }
  render();
  // keep looking for the state for a minute; after 4 s without one, explain why (it may still arrive: then the bracelet shows)
  let tries = 0; const poll = setInterval(() => { if (readState()) { clearInterval(poll); render(); return; } if (++tries === 4) diagnose(); if (tries > 60) clearInterval(poll); }, 1000);
})();
</script>
