  const sur = (XROLL.surname || []).filter(x => !last.has(x.toLowerCase())), sn = sur.length ? pickOf(sur, seed, 'xs', n) : '';
  const out = { t: xTraits(seed, xSlot(n)).map(t => [t.t, t.do]) };
