y dorm":"sky_dormitory","spirit house":"meditation_rooms","storage":"storage_and_lockers","study room":"study_rooms","forest":"forest","island":"willow_island","pavilion":"sparring_pavilion","woods":"forest","viridian dorm":"viridian_dormitory","washrooms":"bathhouse_and_washrooms","willow":"willow_island"},"tune":[{"id":"proficiency","name":"Proficiency","hint":"Weekly practice XP in each field. Class and exam XP are outside this limit.","rows":[{"id":"prof_pace","name":"Proficiency pace","hint":"Practice XP per stat each week.","opts":[[4,"Slow: 4"],[6,"Normal: 6"],[9,"Fast: 9"]],"def":6,"src":""}]},{"id":"training","name":"Training","hint":"How fast training grows your mana pool and stamina, in percent of the value you started with.","rows":[{"id":"trn_session","name":"Gain per session","desc":"What one real session (an hour or more of drilling) adds, before partner bonuses.","opts":[[0.5,"0.5%"],[1,"1%"],[2,"2%"],[3,"3%"]],"def":1,"src":"training.session_pct"},{"id":"trn_week","name":"Weekly limit","desc":"Most that training can add in one week. Gift and Rank 10 jumps ignore it.","opts":[[1.5,"1.5%"],[2.5,"2.5%"],[5,"5%"],[0,"No limit"]],"def":2.5,"src":"training.weekly_pct"},{"id":"trn_total","name":"Lifetime limit","desc":"Most that training can ever add to a track.","opts":[[50,"+50%"],[100,"+100% (twice the start)"],[200,"+200%"],[0,"No limit"]],"def":100,"src":"training.total_pct"}]},{"id":"reputation","name":"Reputation","hint":"How reputation (Academy, Student, Doves) moves.","rows":[{"id":"rep_mult","name":"Pace","desc":"Multiplies every reputation gain and loss (deeds, bond milestones, tension).","opts":[[0.5,"Slow (x0.5)"],[1,"Standard"],[1.5,"Fast (x1.5)"],[2,"Very fast (x2)"]],"def":1,"src":""},{"id":"rep_week","name":"Weekly limit for everyday deeds","desc":"Repeatable good deeds count up to this much a week per reputation; events and losses have no limit.","opts":[[3,"+3"],[5,"+5"],[10,"+10"],[0,"No limit"]],"def":5,"src":"reputation.weekly_cap"},{