res: Study and exams).","rows":[{"id":"study_tiers","name":"Hours for each level of preparation","desc":"Study hours between two exam weeks for shaky / fair / solid / excellent preparation.","opts":[[1,"Light: 2 / 6 / 12 / 20 h"],[2,"Standard: 4 / 10 / 18 / 28 h"],[3,"Demanding: 6 / 15 / 25 / 40 h"]],"def":2,"src":""},{"id":"rank_move","name":"Dorm rank change per Results day","desc":"How far one Results day can move your dorm rank (bands: #1, top 3, top 10, top 25, top 50, the rest).","opts":[[1,"At most one band"],[2,"At most two bands"]],"def":1,"src":""}]},{"id":"fortune","name":"Fortune roll","hint":"How often an important, uncertain attempt by you fails or only partly succeeds (1.9.8). Routine actions never roll.","rows":[{"id":"fortune_band","name":"Difficulty","desc":"Bands of the d100 the engine rolls for each reply, before situational modifiers.","opts":[[1,"Gentle: 1-10 fails, 11-35 partial"],[2,"Standard: 1-20 fails, 21-50 partial"],[3,"Harsh: 1-30 fails, 31-65 partial"]],"def":1,"src":""}]}],"practice":[{"loc":"potion_halls","action":"Brew a potion","stat":"Craft","xp":2,"afterClass":true,"until":1200,"dorm":true},{"loc":"potion_halls","action":"Reagent drill","stat":"Craft","xp":1},{"loc":"main_library","action":"Study a subject","stat":"subject","xp":2,"study":true},{"loc":"study_rooms","action":"Group study","stat":"subject","xp":2,"partner":true,"study":true},{"loc":"archive","action":"Dig through the records","stat":"Knowledge","xp":2},{"loc":"seminar_rooms","action":"Practise wards and counter-curses","stat":"Arcana","xp":2,"afterClass":true},{"loc":"observation_tower","action":"Chart the stars","stat":"Arcana","xp":2,"night":true,"clear":true},{"loc":"meditation_rooms","action":"Will-focus meditation","stat":"Arcana","xp":1,"train":"mana"},{"loc":"spirit_path","action":"Watch the spirits","stat":"Nature","xp":1},{"loc":"spirit_path","action":"Walk with your spirit","stat":"Arcana","xp":1,"pact":true},{"loc":"willow_island","action":"Sit under the