  const sorted = Object.keys(B).sort(by === 'seen' ? (a, b) => (seen(a) - seen(b)) || close(a, b) : by === 'name' ? nm
    : by === 'dorm' || by === 'year' ? (a, b) => (gi(grp(a)) - gi(grp(b))) || grp(a).localeCompare(grp(b)) || nm(a, b) : close);
  if (dir !== P0[2]) sorted.reverse();
