    const b = B[id], n = npcOf(id), pin = pins.includes(id), g = pin ? 'Pinned' : by === 'dorm' || by === 'year' ? grp(id) : pins.length ? 'Everyone else' : '';
    const head = g && g !== last ? `<h3 class="pgh" style="grid-column:1/-1;margin:6px 0 0">${pin ? '★ ' : ''}${esc(g)}</h3>` : '';
