  ['Academy', 'Academy Competition', 'Qualifiers from all four dorms form teams of 4 with at least one student from each year, covering the combat roles between them. Knockout; the winning team represents Halvard.'],
  ['Kingdom', 'Kingdom Competition', 'One team per academy, four in all, three rounds in Avalon: a hunt for three Kingsblooms in the Kingsmeadow (the team without one goes out), the Undercroft under the arena (the two teams holding four rooms at once go through), then the final on the sand. Only the teams travel (Halvard\'s with Gavlan Haverton): they arrive the day before, stay at a hotel and fly home the day after. Each member of the winning team earns 5,000 points.'],
  ['World', 'World Competition', 'Abroad. A panel picks the national four from the best individuals of the Kingdom Competition, winners and losers alike. Being picked off a losing team is a great honour.'],
];
// 1.75.0 (owner-approved planning/DRAFT_club_sendiri.md): the clubs as they are now: the build's list without the students who moved
// to the club {{user}} founded, and that club once founded (shared.js foundedClub), with its room, advisor and members
const clubsNow = S => {
  const F = foundedClub(S), list = (DATA.clubs || []).map(c => F && F.founded ? { ...c, members: c.members.filter(id => !F.members.includes(id)) } : c);
  if (!F || !F.founded) return list;
  const lid = F.venue ? locIdOf(F.venue) : '';
  return [...list, { name: F.name, key: F.name.replace(/\s+club$/i, ''), venues: lid ? [lid] : [], sport: false, practice: false, founded: true,
    members: F.members, advisors: F.advisor ? [F.advisor] : [], follows: [], field: F.field, since: F.since, venue: F.venue }];
};
const clubOf = S => {
  const raw = String(((S.Player || {}).Profile || {}).Club || '').toLowerCase(), c = raw === 'duelling club' ? 'magic duelling club' : raw, all = clubsNow(S);
  return c ? all.find(x => x.founded && x.name.toLowerCase() === c) || all.find(x => !x.founded && c.includes(x.key.toLowerCase())) || null : null;
};
const eventDay = rx => { const e = CAL.EVENTS.find(x => rx.test(x.t)); return e ? { e, di: dayIdx(e.m, e.w, e.d[0]) } : null; };
const daysTo = (S, di) => di - dayIdx(S.World.Month, S.World.Week, S.World.Day);
const whenLabel = n => n < 0 ? 'past' : relDay(n);
// a member shows once their Club field is open (Rank 1)
// 1.88.0 (owner playtest): a teacher's Role line ("advises the X", 1.75.0) is open at Rank 0, so every advisor showed unmet; an advisor
// with no Club field now shows once {{user}} knows it: Rank 1 as a student's Club field, a member of that club, or a known fact names it
const advisorKnown = (id, S, c) => {
  const b = (S.Bonds || {})[id], facts = b ? [...(b.Known_facts || []), ...(b.$Known_old || [])].join(' ') : '';
  return (b ? b.Rank : 0) >= 1 || (clubOf(S) || {}).name === c.name || new RegExp('\\b' + _.escapeRegExp(c.key) + '\\b', 'i').test(facts);
};
const clubFieldOpen = (id, S, c) => { const n = npcOf(id), f = n && n.fl.find(x => x[0].toLowerCase() === 'club'); return f ? fieldUnlocked(id, f, S) : !!c && (c.advisors || []).includes(id) && advisorKnown(id, S, c); };
// the dossier's Role line keeps "; advises the X" back until advisorKnown
const roleShown = (id, text, S) => { const c = clubsNow(S).find(x => !x.founded && (x.advisors || []).includes(id)); return c && !advisorKnown(id, S, c) ? String(text).replace(/;\s*advises the [^.;]*/i, '') : text; };
const hereIs = (S, lid) => !!lid && locIdOf(S.World.Location) === lid;
const aan = w => (/^[aeiou]/i.test(w) ? 'an ' : 'a ') + w;
// 1.99.12 (owner-approved planning/DRAFT_look_for.md): Look for someone. The buttons only draft the line (D3/D6); <now> and the engine
// roll whether that person is there (shared.js lookAsk / lookFor). Here: at a Campus Map place, not after curfew, not in an outside area.
const LOOK_AREAS_UI = ['forest', 'avalon', 'airship', 'sunreach', 'hanakaze'];
const lookIn = name => 'in ' + (/^the /i.test(name) ? name : 'the ' + name);
const lookText = (who, place) => `I'm looking for ${who} ${lookIn(place)}.`;
// 1.99.13 (owner): the tab keeps its id 'practice' (seen ledger, links) and is called Action: Look for someone lives only here,
// then the Practice actions (Proficiency on, a practice place discovered)
const practiceOn = S => featureOn(S, 'proficiency') && practicePlaces(S).length > 0;
const acAction = S => lookRow(S) + (practiceOn(S) ? acPractice(S) : '');
// 2.0.0 (audit A3): where the engine rolls a search at all (Who is here on, not after curfew, not in an outside area); the Action tab
// and the dossier's "Look for <name>" both ask it
const lookOpen = S => featureOn(S, 'presence_roll') && !/CURFEW|LOCKDOWN/.test(String((S.World || {})._Curfew || '')) && !LOOK_AREAS_UI.some(k => (((S.$ui || {}).area || {})[k] || {}).on);
function lookRow(S) {
