// ---- in SillyTavern's chat: the reply that carries the bracelet (the newest visible story reply with MVU's placeholder)
function sceneTarget() {
  try {
    const last = getLastMessageId();
    for (let i = last; i >= Math.max(0, last - 12); i--) {
      const m = (getChatMessages(i) || [])[0];
      if (m && !m.is_hidden && m.role !== 'user' && String(m.message || '').includes(SCENE_PH)) return { id: i, text: String(m.message || '') };
    }
  } catch (e) { /* no chat */ }
  return null;
}
function sceneStyle() {
  ensureFonts();
  let el = PD.getElementById('eldrasil-scene-css'); if (!el) { el = PD.createElement('style'); el.id = 'eldrasil-scene-css'; PD.head.appendChild(el); }
  const css = themed(SCENE_CSS); if (el.textContent !== css) el.textContent = css;
}
let sceneObs = null;
function sceneClear(keep) {
  PD.querySelectorAll('#chat .eld-scene').forEach(x => { if (x !== keep) x.remove(); });
  PD.querySelectorAll('#chat .mes_text.eld-scene-on').forEach(x => { if (!keep || !x.contains(keep)) x.classList.remove('eld-scene-on'); });
}
function sceneRender() {
  try {
    const t = sceneTarget(), st = latestState(), S = st && st.data && st.data.stat_data;
    const mt = t && PD.querySelector(`#chat > .mes[mesid="${t.id}"] .mes_text`);
    // while the reply is being edited its .mes_text holds the edit box: no cards until the edit is saved
    const out = mt && S && !mt.querySelector('textarea') ? sceneHTML(S, t.text) : { html: '' };
    if (sceneObs) { sceneObs.disconnect(); sceneObs = null; }
    if (!out.html) { sceneClear(null); return; }
    sceneStyle();
    let box = mt.querySelector(':scope > .eld-scene');
    if (!box) { box = PD.createElement('div'); box.className = 'eld-scene'; }
    const sig = String(hash32(out.html));
    if (box.dataset.sig !== sig) { box.innerHTML = out.html; box.dataset.sig = sig; }
    // under the narration: before the thoughts block or the state update, else at the end
    const at = mt.querySelector(':scope > details[data-npc-thoughts], :scope > details.eld-uv') || null;
    if (box.parentNode !== mt || (at ? box.nextElementSibling !== at : mt.lastElementChild !== box)) mt.insertBefore(box, at);
    sceneClear(box);
    mt.classList.toggle('eld-scene-on', out.folded);
    // SillyTavern and Tavern Helper rewrite .mes_text (an update, macros): put the cards back when they go
    sceneObs = new MutationObserver(() => { if (!box.isConnected || box.parentNode !== mt) sceneBoot(); });
    sceneObs.observe(mt, { childList: true });
  } catch (e) { console.warn('[Eldrasil] scene cards', e); }
}
const sceneBoot = _.debounce(sceneRender, 250);
// one listener on SillyTavern's document: the cards are rebuilt often, so nothing is bound to them
function sceneClick(e) {
  const b = e.target.closest && e.target.closest('.eld-scene button');
  PD.querySelectorAll('.eld-scene .gift.open').forEach(g => { if (!b || !g.contains(b)) g.classList.remove('open'); });   // any click closes an open gift list
  if (!b) return;
  if (b.dataset.eldGift) { b.parentNode.classList.toggle('open'); return; }
  if (b.dataset.eldFill) { b.closest('.gift') && b.closest('.gift').classList.remove('open'); fillChat(b.dataset.eldFill); return; }
  if (b.dataset.eldOpen) open(b.dataset.eldOpen);
  else if (b.dataset.eldKeep) toggleKeep(b.dataset.eldKeep);
}
function sceneImgError(e) {   // a portrait that fails to load becomes the initials (error does not bubble: capture)
  const img = e.target; if (!img || img.tagName !== 'IMG' || !img.dataset.fb || !img.closest('.eld-scene')) return;
  const sp = PD.createElement('span'); sp.className = img.className + ' fb'; sp.textContent = img.dataset.fb; img.replaceWith(sp);
}



// ---------------------------------------------------------------- dialogue colours (1.37.0)
// The narrator wraps each spoken line in <say:Name>; the card's display regex turns it into <span data-say="Name">. Colours live
// in the card (DATA.say, the engine's $ui.say), never in the prompt: one rule set in SillyTavern's page.
// OKLCH lightness follows the chat theme: light text means a dark theme. Unnamed or unrecorded speakers share the generic colour.
function sayCss(S, lightText) {
  // DATA.say: palette of [dark, light] OKLCH triples [hue, L %, C x100]. A character's colour is $ui.say (the engine's choice for
  // the people present, so nobody in one scene shares one), otherwise their first colour (roster data, or $ui.sayx for Extras)
  const T = lightText ? 0 : 1, ok = c => `oklch(${c[1]}% ${c[2] / 100} ${c[0]})`;
  const q = n => '"' + String(n).trim().toLowerCase().replace(/[^\p{L}\p{N} '.-]/gu, '') + '"', sel = n => `.mes_text span[data-say=${q(n)} i]`;
  const SY = ((S && S.$ui) || {}).say || {}, rules = [`.mes_text span[data-say]{color:${ok(DATA.say.generic[T])}}`], by = {};
  const put = (name, colour) => (by[colour] = by[colour] || []).push(name);
  const SX = ((S && S.$ui) || {}).sayx || {};
  for (const [alias, id] of Object.entries(DATA.say.who)) { const i = id in SY ? SY[id] : (DATA.say.start[id] || [])[0]; if (DATA.say.palette[i]) put(alias, ok(DATA.say.palette[i][T])); }
  for (const name of new Set([...Object.keys(SX), ...Object.keys(SY)])) {
    if (name in DATA.say.start) continue;
    const i = name in SY ? SY[name] : (SX[name] || [])[0];
    if (DATA.say.palette[i]) { put(name, ok(DATA.say.palette[i][T])); put(name.split(/\s+/)[0], ok(DATA.say.palette[i][T])); }
  }
  const user = [((S && S.Player && S.Player.Profile) || {}).Name, typeof SillyTavern === 'object' ? SillyTavern.name1 : ''].filter(n => n && !/\{\{/.test(n));
  for (const n of user) put(n, ok(DATA.say.user[T]));
  for (const [colour, names] of Object.entries(by)) rules.push(`${[...new Set(names.map(n => String(n).toLowerCase()))].map(sel).join(',')}{color:${colour}}`);
  rules.push('.mes_text span[data-tone="shout"]{font-weight:800;font-size:1.08em}',
    '.mes_text span[data-tone="whisper"]{font-size:.9em;font-style:italic;opacity:.8}',
    '.mes_text span[data-tone="measured"]{font-weight:600;letter-spacing:.3px}',
    '.mes_text span[data-tone="tremble"]{font-style:italic;letter-spacing:1px;opacity:.9}');
  return rules.join('\n');
}
// 1.37.3: the preset's NPC Thoughts block (<npc_thoughts>, folded by the preset's regex into details[data-npc-thoughts]) in the
// card's brass, with the story's serif; !important beats the preset's inline style, which stays the look on other cards
function thoughtsCss(lightText) {
  const brass = lightText ? '#c9a364' : '#7d5f34', head = lightText ? '#ecd49f' : '#5e4626';
  return [`.mes_text details[data-npc-thoughts]{border:1px solid color-mix(in srgb,${brass} 40%,transparent)!important;border-left:3px solid ${brass}!important;background:color-mix(in srgb,${brass} 7%,transparent)!important}`,
    `.mes_text details[data-npc-thoughts]>summary{color:${head};font-family:"Alegreya SC","Alegreya",Georgia,serif;letter-spacing:.04em;opacity:1!important}`,
    '.mes_text details[data-npc-thoughts] li,.mes_text details[data-npc-thoughts] p{font-family:"Alegreya",Georgia,serif;font-style:italic}',
    '.mes_text details[data-npc-thoughts] strong{font-style:normal}'].join('\n');
}
function sayStyle() {
  try {
    const st = latestState(), S = st && st.data && st.data.stat_data;
    const c = ((PD.defaultView || window).getComputedStyle(PD.documentElement).getPropertyValue('--SmartThemeBodyColor') || '').match(/\d+(\.\d+)?/g);
    const lightText = !c || (0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]) / 255 > 0.5;
    let el = PD.getElementById('eldrasil-say'); if (!el) { el = PD.createElement('style'); el.id = 'eldrasil-say'; PD.head.appendChild(el); }
    const css = sayCss(S, lightText) + '\n' + thoughtsCss(lightText); if (el.textContent !== css) el.textContent = css;
  } catch (e) { console.warn('[Eldrasil] dialogue colours', e); }
}

// ---------------------------------------------------------------- wiring
if (typeof eventOn === 'function' && typeof getButtonEvent === 'function') {
  $(() => {
    window.parent.__eldrasilUI = true;
    eventOn('eldrasil:open', target => open(String(target || 'profile')));
    eventOn('eldrasil:keep', name => toggleKeep(String(name || '')));   // 1.6.1: the cast strip's pin
    eventOn(getButtonEvent('Student file'), () => open('profile'));
    eventOn(getButtonEvent('Builder'), () => open('builder'));
    eventOn(getButtonEvent('People'), () => open('people'));
    eventOn(getButtonEvent('Map'), () => open('map'));
    eventOn(getButtonEvent('Inventory'), () => open('notebook'));
    eventOn(getButtonEvent('Activities'), () => open('activities'));
    const refresh = _.debounce(() => { if (view.panel === 'profile' || (PANELS[view.panel] && PANELS[view.panel].live)) render(); }, 300);
    const newsBoot = _.debounce(() => { const st = latestState(); if (st) newsInit(st.data.stat_data); }, 800);   // 1.25.0
    ['MESSAGE_RECEIVED', 'MESSAGE_SWIPED', 'CHAT_CHANGED'].forEach(k => tavern_events[k] && eventOn(tavern_events[k], newsBoot));
    setTimeout(newsBoot, 2500);
    ['MESSAGE_RECEIVED', 'MESSAGE_DELETED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED'].forEach(k => tavern_events[k] && eventOn(tavern_events[k], refresh));
    eventOn(tavern_events.CHAT_CHANGED, () => { draft = null; newsMem = null; close(); loreChecked = ''; setTimeout(ensureLorebook, 1200); });
    setTimeout(ensureLorebook, 1500);   // 1.3.6: the card installs or updates its own lorebook
    window.addEventListener('storage', e => { if (e.key === THEME_KEY) applyTheme(); });   // 1.3.1: the theme changed in another tab
    const sayBoot = _.debounce(sayStyle, 300);   // 1.37.0: dialogue colours follow new Extras and the chat theme
    ['MESSAGE_RECEIVED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED', 'CHAT_CHANGED'].forEach(k => tavern_events[k] && eventOn(tavern_events[k], sayBoot));
    setTimeout(sayStyle, 1500);
    // 1.70.0: the scene cards under the newest reply (50_scene.js); the bracelet drops its portrait strip while they run
    window.parent.__eldrasilScene = true;
    ['MESSAGE_RECEIVED', 'MESSAGE_SENT', 'MESSAGE_DELETED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED', 'MESSAGE_EDITED', 'CHARACTER_MESSAGE_RENDERED', 'CHAT_CHANGED'].forEach(k => tavern_events[k] && eventOn(tavern_events[k], sceneBoot));
    eventOn('eldrasil:state', sceneBoot);
    PD.addEventListener('click', sceneClick); PD.addEventListener('error', sceneImgError, true);
    setTimeout(sceneRender, 1500);
    try { eventEmit('eldrasil:state'); } catch (e) { /* the bracelet redraws on its own events */ }
    waitGlobalInitialized('Mvu').then(() => eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => { setTimeout(refresh, 400); newsBoot(); sayBoot(); setTimeout(sceneBoot, 400); }));
    $(window).on('pagehide', () => {
      delete window.parent.__eldrasilUI; delete window.parent.__eldrasilScene; if (host) host.remove(); const s = PD.getElementById('eldrasil-say'); if (s) s.remove();
      PD.removeEventListener('click', sceneClick); PD.removeEventListener('error', sceneImgError, true); sceneClear(null); const c = PD.getElementById('eldrasil-scene-css'); if (c) c.remove();
    });
  });
}

